function ensure3(v){state=v;state.version=3;state.rng=state.rng||20271003;state.scenario=state.scenario||'sandbox';state.difficulty=state.difficulty||'normal';state.scenarioWon=!!state.scenarioWon;state.policy3=state.policy3||{autoCrises:true,crisisLimit:30000,autoRetention:true,retentionLimit:12000};state.incidents=state.incidents||[];state.incidentHistory=state.incidentHistory||[];state.offers=state.offers||[];state.offerHistory=state.offerHistory||[];state.auctions=state.auctions||[];state.supplyDeals=state.supplyDeals||[];state.market3=state.market3||{exclusive:[],lastBid:0};state.warehouses=state.warehouses||[{id:'warehouse-main',name:'Karlín · distribuční sklad',zone:'Praha',capacity:3500,upkeep:2500}];state.routes=state.routes||[];state.deliveryPolicy=state.deliveryPolicy||'express';state.transfers=state.transfers||[];state.forecastDemand=1;state.badges=state.badges||[];state.stores.forEach(store3);for(const e of [...state.stores,...state.roasters,...state.estates])if(e.manager)e.manager=person3(e.manager);for(const r of state.regions)r.manager=person3(r.manager);state.roasters.forEach(r=>r.zone=r.zone||'Praha');state.batches.forEach(b=>b.zone=b.zone||'Praha');state.talents=state.talents||MANAGERS.map((m,i)=>({...m,pid:'candidate-'+i,xp:0,tenure:0,satisfaction:76,ambition:45+i*8,expectedSalary:m.salary,strength:{operations:m.skill,people:clamp(m.skill,1,99),product:clamp(m.skill,1,99)},history:[]}));return state}
fresh=function(scenario='sandbox',difficulty='normal'){if(!SCENARIOS[scenario]||!DIFFICULTIES[difficulty])throw Error('Neznámý scénář nebo obtížnost.');const previous=typeof state==='undefined'?null:state;const v=CORE.fresh();state=v;v.scenario=scenario;v.difficulty=difficulty;const sc=SCENARIOS[scenario];v.cash=sc.cash;v.debt=sc.debt;v.reputation=sc.rep;v.brands[0].reputation=sc.rep;if(scenario==='family'){v.stores[0]=CORE.makeStore('letna');v.roasters[0].capacity=80;v.roasters[0].upkeep=2000;v.brands[0].name='Rodinná kavárna';}if(scenario==='rescue'){v.stores=[CORE.makeStore('karlin'),CORE.makeStore('letna'),CORE.makeStore('vinohrady')];v.stores.forEach(s=>{s.quality=48;s.staff=5;s.marketing=4000;s.wage=7000});v.roasters[0].capacity=180;v.roasters[0].condition=58;}if(scenario==='premium'){v.stores[0]=CORE.makeStore('vinohrady');v.brands[0].concept='specialty';v.brands[0].name='Atelier du Café';v.blends[0]={...v.blends[0],name:'Highland Bloom',primary:'ethiopia',secondary:'kenya',share:80,roast:1,packaging:'premium',price:740};v.green=[{origin:'ethiopia',kg:110,cost:360,quality:94},{origin:'kenya',kg:70,cost:390,quality:96}];v.batches=[{blend:'blend-1',kg:45,quality:94,cost:515,roastedWeek:1}];}v.logs=[{week:1,text:'Scénář: '+sc.name,detail:sc.description}];ensure3(v);state=previous||v;return v;};
state=ensure3(state);
makeStore=function(...args){return store3(CORE.makeStore(...args))};
function random3(){let x=state.rng|0;x^=x<<13;x^=x>>>17;x^=x<<5;state.rng=x>>>0;return state.rng/4294967296}
function difficulty3(){return DIFFICULTIES[state.difficulty]}
function menuSummary(s){store3(s);const l=loc(s.id),warm=((state.week-1)%52>=20&&(state.week-1)%52<=36);const drinks=[];for(const [k,item] of Object.entries(s.menu)){const m=MENU[k];if(!item.enabled||m.food||m.requires&&!s.equipment[m.requires])continue;let weight=m.weight;if(k==='filter'&&l.segment==='specialty')weight*=1.6;if(k==='coldbrew')weight*=warm?2:.6;if(k==='seasonal')weight*=1.25;if(k==='espresso'&&l.segment==='office')weight*=1.3;drinks.push({id:k,...m,...item,weight})}const total=drinks.reduce((a,m)=>a+m.weight,0);const average=(key)=>total?drinks.reduce((a,m)=>a+m[key]*m.weight,0)/total:0;let foodRevenue=0,foodCost=0,foodMinutes=0;const food=[];for(const [k,item] of Object.entries(s.menu)){const m=MENU[k];if(!m.food||!item.enabled||!s.equipment[m.requires])continue;const rate=k==='pastry'?.22:.14;foodRevenue+=rate*item.price;foodCost+=rate*m.cost;foodMinutes+=rate*m.minutes;food.push({id:k,rate,...m,...item})}return {drinks,food,total,price:average('price'),cost:average('cost'),dose:average('dose'),minutes:average('minutes')+foodMinutes,foodRevenue,foodCost,hasDrinks:!!total};}
function shiftMenu(s,delta){for(const [k,m] of Object.entries(s.menu))if(!MENU[k].food)m.price=clamp(m.price+delta,35,350);s.menuAnchor=s.price}
function updateMenu(id,key,data){guard();const s=state.stores.find(s=>s.id===id);if(!s||!MENU[key]||!Number.isInteger(data.price)||data.price<35||data.price>350||typeof data.enabled!=='boolean')throw Error('Cena položky musí být 35–350 Kč.');s.menu[key]={...data};const summary=menuSummary(s);if(summary.hasDrinks){s.price=round(summary.price);s.menuAnchor=s.price}log('Menu upraveno: '+loc(id).name,MENU[key].name+' · '+money(data.price)+(data.enabled?' · v nabídce':' · vyřazeno'));}
function buyEquipment(id,key){guard();const s=state.stores.find(s=>s.id===id),e=EQUIPMENT[key];if(!s||!e||s.equipment[key])throw Error('Vybavení už máš nebo neexistuje.');spend(e.cost);s.equipment[key]={condition:100};if(key==='seats')s.seats+=12;log('Vybavení: '+loc(id).name,e.name+' · '+money(e.cost));}
function serviceEquipment(id,key){guard();const s=state.stores.find(s=>s.id===id);if(!s?.equipment[key])throw Error('Vybavení není instalované.');spend(round(EQUIPMENT[key].cost*.08));s.equipment[key].condition=100;s.serviceCondition=100;state.pendingExpense3=(state.pendingExpense3||0)+round(EQUIPMENT[key].cost*.08);log('Servis zařízení: '+loc(id).name,EQUIPMENT[key].name);}
function equipmentEffects(s){let capacity=1,quality=0,cost=0;for(const [key,e] of Object.entries(s.equipment)){const cfg=EQUIPMENT[key];capacity*=1+(cfg.capacity-1)*e.condition/100;quality+=cfg.quality*e.condition/100;cost+=cfg.maintenance;}return {capacity:clamp(capacity,.5,1.65),quality,cost};}
function setLayout(id,layout){guard();const s=state.stores.find(s=>s.id===id);if(!s||!['balanced','speed','lounge'].includes(layout))throw Error('Neplatné uspořádání.');if(s.layout!==layout)spend(25000);s.layout=layout;log('Nové uspořádání: '+loc(id).name,layout==='speed'?'Rychlá obsluha.':layout==='lounge'?'Pobyt a komunitní zážitek.':'Vyvážený provoz.');}
autoManager=function(s){store3(s);if(s.price!==s.menuAnchor)shiftMenu(s,s.price-s.menuAnchor);const before=s.price,result=CORE.autoManager(s);if(s.price!==before)shiftMenu(s,s.price-before);const summary=menuSummary(s);s.menuStats=summary;s.price=clamp(round(summary.price),40,400);s.menuAnchor=s.price;return result};
demandForStore=function(s,weekFactor){const base=CORE.demandForStore(s,weekFactor),m=s.menuStats||menuSummary(s),e=equipmentEffects(s);const active=activeIncidents('store',s.id);const disruption=active.reduce((a,i)=>a*(i.type==='absence'?.72:i.type==='badbatch'?.82:i.type==='review'?.92:1),1);const route=routeService(s);const variety=clamp(1+(m.drinks.length-2)*.025,.85,1.12),layout=s.layout==='lounge'?(loc(s.id).segment==='community'?1.1:1.02):s.layout==='speed'?(loc(s.id).segment==='office'?1.06:1):1;const demand=round(base.demand*variety*layout*(s.layout==='lounge'?clamp(s.seats/24,.8,1.25):1)*difficulty3().demand*(state.forecastDemand||1));const rate=1.55/Math.max(.75,m.minutes),capacity=s.staff*(brand(s.brand).concept==='express'?450:380)*rate*e.capacity*(s.layout==='speed'?1.13:s.layout==='lounge'?.9:1)*(s.serviceCondition/100)*disruption*route.reliability;let potential=m.hasDrinks?Math.min(demand,round(capacity)):0;s.quality=round(clamp(s.quality+e.quality*.2-(route.agePenalty||0),15,99));return {...base,demand,potential,extraCosts:e.cost+route.cost,foodRevenue:m.foodRevenue,ingredientCost:m.cost+m.foodCost,dose:m.dose||.018,route,menu:m};};
function entityFor(kind,id){return (kind==='store'?state.stores:kind==='roaster'?state.roasters:kind==='estate'?state.estates:state.regions).find(e=>kind==='region'?e.city===id:e.id===id)}
function staffAssignments(){const result=[];for(const kind of ['store','roaster','estate','region']){const list=kind==='store'?state.stores:kind==='roaster'?state.roasters:kind==='estate'?state.estates:state.regions;for(const e of list)if(e.manager)result.push({kind,id:kind==='region'?e.city:e.id,entity:e,person:e.manager,label:kind==='store'?loc(e.id).name:e.name||e.city})}return result}
function recruitProfile(templateIndex=0){const m=MANAGERS[templateIndex%MANAGERS.length],used=staffAssignments().some(a=>a.person.name===m.name);const first=['Adam','Klára','Martin','Sofie','Jakub','Tereza','Filip','Lucie','Matěj','Adéla','Pavel','Nela'];const last=['Dvořák','Bílá','Horák','Svobodová','Černý','Pokorná','Král','Procházková','Beneš','Sedláčková','Urban','Marková'];const n=state.nextId;return person3({...m,name:used?first[n%first.length]+' '+last[Math.floor(n/first.length)%last.length]:m.name,initials:used?(first[n%first.length][0]+last[Math.floor(n/first.length)%last.length][0]):m.initials})}
hire=function(id,index,kind='store'){guard();const e=entityFor(kind,id);if(!e||!MANAGERS[index])throw Error('Neplatný výběr.');spend(Math.max(4000,12000-state.departments.hr*1500));e.manager=recruitProfile(index);log(e.manager.name+' nastupuje: '+(e.name||loc(id).name),'Dovednost '+e.manager.skill+'/100. Mzda '+money(e.manager.salary)+'/týden.');};
function hireCandidate(id,pid,kind='store'){guard();const e=entityFor(kind,id),i=state.talents.findIndex(p=>p.pid===pid);if(!e||i<0)throw Error('Kandidát už není dostupný.');spend(Math.max(4000,12000-state.departments.hr*1500));if(e.manager)state.talents.push({...e.manager,tenure:0});e.manager=state.talents.splice(i,1)[0];log(e.manager.name+' přebírá '+(e.name||loc(id)?.name||id),'Kariéra a zkušenosti zůstávají zachované.');}
function trainPerson(pid,focus){guard();const a=staffAssignments().find(a=>a.person.pid===pid);if(!a||!['operations','people','product'].includes(focus))throw Error('Neplatná osoba nebo školení.');spend(state.departments.hr?12000:18000);a.person.strength[focus]=clamp(a.person.strength[focus]+4,1,99);a.person.skill=round(Object.values(a.person.strength).reduce((a,n)=>a+n,0)/3);a.person.xp+=15;a.person.satisfaction=clamp(a.person.satisfaction+5,0,100);a.person.history.unshift({week:state.week,text:'Školení: '+focus});log('Školení: '+a.person.name,'Zvolená dovednost +4.');}
function raisePerson(pid){guard();const a=staffAssignments().find(a=>a.person.pid===pid);if(!a)throw Error('Osoba už ve firmě nepracuje.');a.person.salary=Math.min(50000,round(a.person.salary*1.12));a.person.satisfaction=clamp(a.person.satisfaction+12,0,100);log('Mzda upravena: '+a.person.name,money(a.person.salary)+' / týden.');}
function promotePerson(pid,city){guard();const a=staffAssignments().find(a=>a.person.pid===pid);if(!a||a.kind==='region'||!CITIES.some(c=>c.name===city)||state.regions.some(r=>r.city===city))throw Error('Neplatné povýšení nebo region už má ředitele.');if(!officeSeats()||usedSeats()+1>officeSeats())throw Error('V kanceláři potřebuješ volné místo.');if(a.person.tenure<4&&a.person.skill<85)throw Error('Povýšení vyžaduje čtyři týdny zkušeností nebo dovednost alespoň 85.');spend(20000);const m=a.person;a.entity.manager=null;m.satisfaction=clamp(m.satisfaction+15,0,100);m.history.unshift({week:state.week,text:'Povýšení do regionu '+city});state.regions.push({city,manager:m,auto:true,last:[]});log('Povýšení: '+m.name,'Oblastní ředitel pro '+city+'.');}
function processCareers(){for(const a of staffAssignments()){const p=a.person;person3(p);p.tenure++;p.xp+=1+Math.min(3,state.departments.hr*.5);if(p.xp>=20){p.xp-=20;p.strength.operations=clamp(p.strength.operations+1,1,99);p.skill=round(Object.values(p.strength).reduce((a,n)=>a+n,0)/3);p.history.unshift({week:state.week,text:'Další provozní zkušenost.'})}const pay=p.salary/p.expectedSalary,load=a.kind==='region'?state.stores.filter(s=>loc(s.id).city===a.id).length/6:a.kind==='store'?(a.entity.last?.lost||0)/Math.max(1,loc(a.id).traffic):a.kind==='roaster'?(a.entity.last?.utilization||0):a.entity.health<65?1:0;p.satisfaction=clamp(p.satisfaction+(pay-1)*2+Math.min(1,state.departments.hr*.2)-(load>1?(load-1)*1.5:.1)+(state.history.at(-1)?.profit>0?.15:-.5),0,100);p.history=p.history.slice(0,10);if(p.satisfaction<25){if(a.kind==='region')state.regions=state.regions.filter(r=>r!==a.entity);else a.entity.manager=null;log('Odchod: '+p.name,'Dlouhodobá spokojenost klesla pod 25. Vedení provozu je volné.');}}
if(state.week%5===0&&state.talents.length<8){const p=recruitProfile(state.week%4);p.skill=clamp(p.skill-4+round(random3()*8),65,97);p.strength={operations:p.skill,people:p.skill,product:p.skill};state.talents.push(p)}
if(state.week%9===0&&staffAssignments().length&&state.rivals.some(r=>!r.bankrupt)){const people=staffAssignments().filter(a=>!state.offers.some(o=>o.pid===a.person.pid)).sort((a,b)=>b.person.skill-a.person.skill);const a=people[0],r=state.rivals.find(r=>!r.bankrupt&&r.cash>150000);if(a&&r){const offer={id:uid('offer'),pid:a.person.pid,name:a.person.name,rival:r.id,salary:Math.min(50000,round(a.person.salary*1.22)),due:state.week+2};state.offers.push(offer);log('Konkurence oslovila '+a.person.name,r.name+' nabízí '+money(offer.salary)+'/týden. Rozhodni do týdne '+offer.due+'.')}}
for(const o of [...state.offers]){const a=staffAssignments().find(a=>a.person.pid===o.pid);if(!a){state.offers=state.offers.filter(x=>x.id!==o.id);continue}if(state.policy3.autoRetention&&state.departments.hr>0&&o.salary<=state.policy3.retentionLimit&&state.cash>weeklyFixed()*3){resolveOffer(o.id,'match',true);continue}if(state.week>=o.due){resolveOffer(o.id,a.person.satisfaction>=75?'stay':'leave',true)}}}
function resolveOffer(id,choice,automatic=false){guard();const o=state.offers.find(o=>o.id===id),a=o&&staffAssignments().find(a=>a.person.pid===o.pid),r=o&&state.rivals.find(r=>r.id===o.rival);if(!a||!['match','stay','leave'].includes(choice))throw Error('Nabídka už není aktuální.');if(choice==='match'){a.person.salary=o.salary;a.person.satisfaction=clamp(a.person.satisfaction+10,0,100);log('Udržen talent: '+o.name,(automatic?'HR automaticky dorovnalo nabídku. ':'')+'Nová mzda '+money(o.salary)+'.')}else if(choice==='leave'||a.person.satisfaction<75){if(a.kind==='region')state.regions=state.regions.filter(r=>r!==a.entity);else a.entity.manager=null;if(r&&r.cash>o.salary*4){r.cash-=o.salary*4;r.reputation=clamp(r.reputation+1,0,99)}log(o.name+' přechází ke konkurenci','Vedení provozu je potřeba doplnit.')}else log(o.name+' zůstává ve firmě','Spokojenost alespoň 75 převážila vyšší nabídku.');state.offerHistory.unshift({...o,choice,week:state.week});state.offerHistory=state.offerHistory.slice(0,20);state.offers=state.offers.filter(x=>x.id!==id);}
function activeIncidents(kind,target){return state.incidents.filter(i=>i.kind===kind&&i.target===target&&!i.resolved)}
const CRISIS_CHOICES={absence:[{id:'overtime',label:'Přesčasy a záskok',cost:12000},{id:'hire',label:'Posílit tým natrvalo',cost:22000},{id:'wait',label:'Omezit kapacitu tento týden',cost:0}],breakdown:[{id:'repair',label:'Opravit pražičku',cost:24000},{id:'outsource',label:'Servis a náhradní technik',cost:32000},{id:'wait',label:'Odložit opravu',cost:0}],review:[{id:'reply',label:'Vyřešit reklamaci a odpovědět',cost:4000},{id:'improve',label:'Školení a péče o hosty',cost:14000},{id:'wait',label:'Bez reakce',cost:0}],badbatch:[{id:'recall',label:'Stáhnout šarži a nahradit nabídku',cost:10000},{id:'discount',label:'Přiznat problém a dát slevu',cost:6000},{id:'wait',label:'Neřešit',cost:0}],delivery:[{id:'express',label:'Expresní přeprava',cost:18000},{id:'backup',label:'Záložní dodavatel',cost:26000},{id:'wait',label:'Počkat na dodávku',cost:0}]};
function generateIncident(){const types=['absence','review','badbatch'];if(state.roasters.length)types.push('breakdown');if(state.shipments.length)types.push('delivery');const type=types[Math.floor(random3()*types.length)];let kind='store',target=state.stores[Math.floor(random3()*state.stores.length)].id,title='',details='';if(type==='breakdown'){kind='roaster';const r=state.roasters[Math.floor(random3()*state.roasters.length)];target=r.id;r.condition=Math.min(r.condition,38);title='Porucha: '+r.name;details='Stav pražičky klesl na 38. Kapacita je omezená do opravy.';}if(type==='delivery'){kind='shipment';const s=state.shipments[0];target=s.id;s.due+=2;title='Zpoždění dodávky';details=s.source+' · '+round(s.kg)+' kg. Příjezd odložen o dva týdny.';}if(type==='absence'){title='Výpadek týmu: '+loc(target).name;details='Do vyřešení je provozní kapacita nižší o 28 %.';}if(type==='review'){title='Reklamace: '+loc(target).name;details='Nespokojený host. Nevyřešená reklamace snižuje zájem o pobočku o 8 %.';}if(type==='badbatch'){title='Kontrola chuti: '+loc(target).name;details='Podezření na vadnou šarži. Do vyřešení je zájem o pobočku nižší o 18 %.';}if(state.incidents.some(i=>i.target===target))return;const i={id:uid('incident'),type,kind,target,title,details,created:state.week,due:state.week+2};state.incidents.push(i);log(title,details+' Rozhodnutí do týdne '+i.due+'.');}
function resolveIncident(id,choice,automatic=false){guard();const i=state.incidents.find(i=>i.id===id),c=i&&CRISIS_CHOICES[i.type].find(c=>c.id===choice);if(!i||!c)throw Error('Problém nebo řešení už není aktuální.');spend(c.cost);if(state.turnLedger3)state.turnLedger3.crises+=c.cost;else state.pendingExpense3=(state.pendingExpense3||0)+c.cost;const s=state.stores.find(s=>s.id===i.target),r=state.roasters.find(r=>r.id===i.target);if(i.type==='absence'){if(choice==='hire'&&s)s.staff=Math.min(7,s.staff+1);if(choice==='wait'&&s)s.loyalty=clamp(s.loyalty-3,0,80)}if(i.type==='breakdown'&&r){if(choice==='repair'||choice==='outsource')r.condition=100;else r.condition=Math.max(20,r.condition-5)}if(i.type==='review'&&s){brand(s.brand).reputation=clamp(brand(s.brand).reputation+(choice==='wait'?-3:choice==='improve'?2:1),0,99);if(choice==='improve')s.quality=clamp(s.quality+3,0,99)}if(i.type==='badbatch'&&s){if(choice==='recall'){const bad=state.batches.filter(b=>b.blend===s.blend&&b.zone===loc(s.id).city).sort((a,b)=>b.roastedWeek-a.roastedWeek)[0];if(bad){const loss=bad.kg*bad.cost;state.batches=state.batches.filter(b=>b!==bad);if(state.turnLedger3)state.turnLedger3.writeoff+=loss;else state.pendingWriteoff3=(state.pendingWriteoff3||0)+loss}}if(choice==='wait')s.quality=clamp(s.quality-6,0,99);if(choice==='discount')s.loyalty=clamp(s.loyalty+1,0,80)}if(i.type==='delivery'){const ship=state.shipments.find(s=>s.id===i.target);if(ship&&choice==='express')ship.due=state.week;if(ship&&choice==='backup'){const kg=Math.min(40,ship.kg),unit=ORIGINS[ship.origin].cost*1.25;state.green.push({origin:ship.origin,kg,cost:unit,quality:ORIGINS[ship.origin].quality});if(state.turnLedger3)state.turnLedger3.crises-=kg*unit;else state.pendingExpense3-=kg*unit;}}const result={...i,choice,automatic,resolvedWeek:state.week,cost:c.cost};state.incidentHistory.unshift(result);state.incidentHistory=state.incidentHistory.slice(0,40);state.incidents=state.incidents.filter(x=>x.id!==id);log((automatic?'Vedení vyřešilo: ':'Vyřešeno: ')+i.title,c.label+' · '+money(c.cost));}
function processIncidents(){for(const i of [...state.incidents]){const e=entityFor(i.kind,i.target),region=i.kind==='store'&&state.regions.find(r=>r.city===loc(i.target)?.city),canDelegate=state.policy3.autoCrises&&(e?.manager?.skill>=75||region?.manager?.skill>=80||i.kind==='shipment'&&state.departments.sales>0),preferred=CRISIS_CHOICES[i.type].find(c=>c.id!=='wait'&&c.cost<=state.policy3.crisisLimit);if(canDelegate&&preferred&&state.cash>weeklyFixed()*2+preferred.cost){resolveIncident(i.id,preferred.id,true)}else if(state.week>=i.due){resolveIncident(i.id,'wait',true)}}}
function regionalStock(id,city){return state.batches.filter(b=>b.blend===id&&(b.zone||'Praha')===city).reduce((a,b)=>a+b.kg,0)}
stock=function(id,city){return city?regionalStock(id,city):CORE.stock(id)};
function warehouseCapacity(city){return 150+state.warehouses.filter(w=>w.zone===city).reduce((a,w)=>a+w.capacity,0)}
function cityStock(city){return state.batches.filter(b=>b.zone===city).reduce((a,b)=>a+b.kg,0)}
function buyWarehouse(city,name,size=1000){guard();if(!CITIES.some(c=>c.name===city)||!name?.trim()||name.length>50||![1000,3000,6000].includes(size))throw Error('Neplatný sklad.');spend(size*95);const w={id:uid('warehouse'),zone:city,name:name.trim(),capacity:size,upkeep:round(size*.95)};state.warehouses.push(w);log('Nový sklad: '+city,name+' · '+size+' kg kapacity.');return w;}
function transportProfile(from,to,mode='standard'){const same=zoneOf(from)===zoneOf(to);return {weeks:mode==='air'?1:same?1:2,cost:mode==='air'?same?12:38:same?5:16,agePenalty:same?0:mode==='air'?1:3};}
function createRoute(from,to,blendId,kg,mode){guard();if(from===to||!CITIES.some(c=>c.name===from)||!CITIES.some(c=>c.name===to)||!blend(blendId)||!Number.isInteger(kg)||kg<5||kg>500||!['standard','air'].includes(mode))throw Error('Trasa potřebuje dvě různá města a 5–500 kg týdně.');if(!state.warehouses.some(w=>w.zone===to))throw Error('Nejdřív pořiď sklad v cílovém městě.');spend(12000);state.routes.push({id:uid('route'),from,to,blend:blendId,kg,mode,active:true,last:null});log('Nová zásobovací trasa',from+' → '+to+' · '+kg+' kg týdně.');}
function processTransfers(){for(const t of [...state.transfers])if(t.due<=state.week){const room=Math.max(0,warehouseCapacity(t.to)-cityStock(t.to));if(room<t.kg){t.due++;log('Dodávka čeká před skladem: '+t.to,'Chybí '+round(t.kg-room)+' kg skladové kapacity.');continue}for(const b of t.batches)state.batches.push({...b,zone:t.to});state.transfers=state.transfers.filter(x=>x.id!==t.id);log('Regionální dodávka dorazila',t.from+' → '+t.to+' · '+round(t.kg)+' kg.')}}
function takeRegionalCoffee(id,kg,city,allowRemote=false){let remaining=kg,cost=0,quality=0,used=0,remote=0,remoteCost=0;const lots=state.batches.filter(b=>b.blend===id&&(b.zone===city||allowRemote)).sort((a,b)=>((a.zone===city?0:1)-(b.zone===city?0:1))||a.roastedWeek-b.roastedWeek);for(const b of lots){if(remaining<=.00001)break;const n=Math.min(b.kg,remaining),isRemote=b.zone!==city;b.kg-=n;remaining-=n;cost+=n*b.cost;quality+=n*batchQuality(b);used+=n;if(isRemote){remote+=n;remoteCost+=n*(zoneOf(b.zone)===zoneOf(city)?12:38);}}state.batches=state.batches.filter(b=>b.kg>.001);return {kg:used,cost,quality:used?quality/used:coffeeQuality(id),remote,remoteCost};}
function takeCoffeeForStore(s,kg){const result=takeRegionalCoffee(s.blend,kg,loc(s.id).city,state.deliveryPolicy==='express');if(result.remote&&state.turnLedger3){const cost=result.remoteCost;state.turnLedger3.transport+=cost;state.cash-=cost;}return result;}
function routeService(s){const city=loc(s.id).city,needed=loc(s.id).traffic*(s.menuStats?.dose||.018)*1.1,local=regionalStock(s.blend,city),hasProduction=state.roasters.some(r=>r.zone===city);return {reliability:1,cost:0,agePenalty:!hasProduction&&zoneOf(city)!=='europe'&&state.deliveryPolicy==='express'?1:0,local,needed,express:state.deliveryPolicy==='express'};}
function dispatchRoutes(){for(const r of state.routes){if(!r.active)continue;const incoming=state.transfers.filter(t=>t.to===r.to&&t.blend===r.blend).reduce((a,t)=>a+t.kg,0),need=productionNeeds(r.to)[r.blend]||r.kg,room=Math.max(0,warehouseCapacity(r.to)-cityStock(r.to)-incoming),amount=Math.min(r.kg,regionalStock(r.blend,r.from),room,Math.max(0,need*1.8-regionalStock(r.blend,r.to)-incoming));if(amount<.1){r.last={kg:0,cost:0,reason:room<=0?'Cílový sklad je plný.':'Zásoba je pokrytá nebo chybí káva ve zdroji.'};continue}const profile=transportProfile(r.from,r.to,r.mode),cost=amount*profile.cost;if(state.cash<cost+weeklyFixed()){r.last={kg:0,cost:0,reason:'Chybí hotovostní rezerva.'};continue}const moved=[];let left=amount;for(const b of state.batches.filter(b=>b.blend===r.blend&&b.zone===r.from).sort((a,b)=>a.roastedWeek-b.roastedWeek)){if(left<=0)break;const n=Math.min(b.kg,left);b.kg-=n;left-=n;moved.push({...b,kg:n});}state.batches=state.batches.filter(b=>b.kg>.001);state.cash-=cost;if(state.turnLedger3)state.turnLedger3.transport+=cost;state.transfers.push({id:uid('transfer'),from:r.from,to:r.to,blend:r.blend,kg:amount,batches:moved,due:state.week+profile.weeks});r.last={kg:round(amount*10)/10,cost:round(cost),reason:'Odesláno, příjezd v týdnu '+(state.week+profile.weeks)+'.'};}}
productionNeeds=function(city){const needs={};for(const s of state.stores){if(city&&loc(s.id).city!==city&&!(city==='Praha'&&state.deliveryPolicy==='express'&&!state.roasters.some(r=>r.zone===loc(s.id).city&&r.auto)))continue;const dose=menuSummary(s).dose||.018;needs[s.blend]=(needs[s.blend]||0)+loc(s.id).traffic*dose*1.22;}if(!city||city==='Praha'){for(const c of state.contracts)needs[c.blend]=(needs[c.blend]||0)+c.kg;if(state.projects.eshop.done&&state.departments.it)for(const b of state.blends)needs[b.id]=(needs[b.id]||0)+Math.max(2,state.reputation*.06);}for(const r of state.routes.filter(r=>r.active&&(!city||r.from===city)))needs[r.blend]=(needs[r.blend]||0)+r.kg;return needs;};
roastBatch=function(r,b,kg,emergency=false){const room=warehouseCapacity(r.zone||'Praha')-cityStock(r.zone||'Praha');if(room<kg*.84)throw Error('Sklad pražírny nemá dost volné kapacity.');const before=state.batches.length,result=CORE.roastBatch(r,b,kg,emergency);state.batches.slice(before).forEach(lot=>{lot.zone=r.zone||'Praha';lot.id=uid('batch')});return result;};
buyRoaster=function(type,name,city='Praha'){if(!CITIES.some(c=>c.name===city))throw Error('Neznámé město výroby.');const r=CORE.buyRoaster(type,name);r.zone=city;return r;};
autoProduction=function(){const result=CORE.autoProduction();dispatchRoutes();return result};
function getBeanCost(origin){const exclusive=state.market3.exclusive.find(d=>d.origin===origin&&d.until>=state.week);return ORIGINS[origin].cost*(exclusive?1.12:1);}
orderBeans=function(origin,kg){guard();if(!ORIGINS[origin]||!Number.isInteger(kg)||kg<1||kg>2500)throw Error('Objednávka musí být 1–2 500 kg.');const unit=getBeanCost(origin);spend(kg*unit);state.shipments.push({id:uid('shipment'),origin,kg,cost:unit,quality:ORIGINS[origin].quality,due:state.week+1,source:'Dodavatel'});log('Objednáno '+kg+' kg: '+ORIGINS[origin].name,'Cena '+money(unit)+'/kg, příjezd v týdnu '+(state.week+1)+'.');};
function signSupply(origin,kg){guard();if(!ORIGINS[origin]||!Number.isInteger(kg)||kg<20||kg>500||state.supplyDeals.some(d=>d.origin===origin))throw Error('Smlouva potřebuje 20–500 kg týdně a volný původ.');spend(35000);state.supplyDeals.push({id:uid('supply'),origin,kg,price:round(getBeanCost(origin)*.87),remaining:16,active:true});log('Rámcová smlouva: '+ORIGINS[origin].name,kg+' kg týdně na 16 týdnů, sleva 13 %.');}
function processSupply(){for(const d of state.supplyDeals){if(!d.active)continue;const cost=d.kg*d.price;if(state.cash>cost+weeklyFixed()){state.cash-=cost;state.shipments.push({id:uid('shipment'),origin:d.origin,kg:d.kg,cost:d.price,quality:ORIGINS[d.origin].quality,due:state.week+1,source:'Rámcová smlouva'});if(state.turnLedger3)state.turnLedger3.supply+=cost;d.remaining--;}else log('Dodávka smlouvy pozastavena','Není rezerva pro '+ORIGINS[d.origin].name+'.');}state.supplyDeals=state.supplyDeals.filter(d=>d.remaining>0);state.market3.exclusive=state.market3.exclusive.filter(d=>d.until>=state.week);}
function bidAuction(id,amount){guard();const a=state.auctions.find(a=>a.id===id);if(!a||a.closed||!Number.isInteger(amount)||amount<a.highest+10000)throw Error('Příhoz musí být alespoň 10 000 Kč nad nejvyšší nabídku.');if(state.cash<amount+loc(a.location).setup)throw Error('Ponech hotovost na příhoz i otevření kavárny.');a.highest=amount;a.leader='player';a.playerBid=amount;log('Příhoz na '+loc(a.location).name,money(amount)+' za přednostní nájemní právo.');}
function processAuctions(){for(const a of [...state.auctions]){if(a.closed)continue;const l=loc(a.location);for(const r of state.rivals.filter(r=>!r.bankrupt)){if(random3()<.42&&r.cash>l.setup+a.highest+220000&&a.highest<l.setup*.4){a.highest+=10000;a.leader=r.id}}if(state.week>=a.due){const leader=state.rivals.find(r=>r.id===a.leader);if(a.leader==='player'&&state.cash>=a.highest+l.setup){state.cash-=a.highest;state.market3.exclusive.push({location:a.location,holder:'player',until:state.week+4});if(state.turnLedger3)state.turnLedger3.auctions+=a.highest;log('Vyhraná aukce: '+l.city+' · '+l.name,'Právo na otevření po čtyři týdny. Cena '+money(a.highest)+'.')}else if(leader&&leader.cash>l.setup+a.highest){leader.cash-=l.setup+a.highest;leader.stores.push(l.id);log('Aukci vyhrál '+leader.name,l.city+' · '+l.name+' za příplatek '+money(a.highest)+'.')}a.closed=true;a.result=a.leader;a.closedWeek=state.week;}}
state.auctions=state.auctions.filter(a=>!a.closed||state.week-(a.closedWeek||0)<8);if(state.week%8===0&&!state.auctions.some(a=>!a.closed)){const list=LOCATIONS.filter(l=>unlocked(l.city)&&!owned(l.id)&&!occupant(l.id)&&!state.market3.exclusive.some(e=>e.location===l.id));list.sort((a,b)=>b.traffic-a.traffic);if(list[0]){const l=list[0];state.auctions.push({id:uid('auction'),location:l.id,highest:20000,leader:null,playerBid:0,due:state.week+2,closed:false});log('Aukce o lokalitu: '+l.city+' · '+l.name,'Nájemní právo se draží do týdne '+(state.week+2)+'.')}}}
openStore=function(id,...args){const auction=state.auctions.find(a=>!a.closed&&a.location===id),exclusive=state.market3.exclusive.find(a=>a.location===id&&a.until>=state.week);if(auction)throw Error('O tuto lokalitu probíhá aukce. Nejdřív získej nájemní právo.');if(exclusive&&exclusive.holder!=='player')throw Error('Na lokalitu má dočasně právo konkurence.');CORE.openStore(id,...args);const created=state.stores.at(-1);if(created.manager)created.manager=person3(created.manager);state.market3.exclusive=state.market3.exclusive.filter(a=>a.location!==id)};
function companyValue(){return round(Math.max(0,state.cash)+state.stores.reduce((a,s)=>a+loc(s.id).setup*(s.franchise?.2:.8),0)+state.roasters.reduce((a,r)=>a+r.capacity*2400,0)+state.offices.reduce((a,o)=>a+o.cost,0)+state.estates.reduce((a,e)=>a+e.cost,0)+Math.max(0,state.history.slice(-4).reduce((a,h)=>a+h.profit,0)/Math.max(1,state.history.slice(-4).length))*12-state.debt)}
function resolveBuyout(accept){guard();if(!state.buyout||state.buyout.due<state.week)throw Error('Nabídka už není aktuální.');const r=state.rivals.find(r=>r.id===state.buyout.rival);if(accept){if(!r||r.cash<state.buyout.amount)throw Error('Kupující nemá prostředky.');r.cash-=state.buyout.amount;state.dividends+=state.buyout.amount*state.founderShare/100;state.sold=true;state.over=true;log('Firma prodána: '+r.name,'Zakladatel obdržel '+money(state.buyout.amount*state.founderShare/100)+'.');}else log('Nabídka na odkup odmítnuta','Pokračuješ s vlastní firmou.');state.buyout=null;}
simulateRivals=function(){const normalWeek=state.week;const cadence=difficulty3().rivalEvery;if(normalWeek%cadence!==0&&normalWeek%4===0)state.week=normalWeek+1;else if(normalWeek%cadence===0&&normalWeek%4!==0)state.week=normalWeek+(4-normalWeek%4);CORE.simulateRivals();state.week=normalWeek;for(const r of state.rivals.filter(r=>!r.bankrupt)){if(state.week%12===0&&r.cash>300000&&random3()<.55){const origins=['colombia','ethiopia','kenya'],origin=origins[Math.floor(random3()*origins.length)];if(!state.market3.exclusive.some(d=>d.origin===origin)){r.cash-=45000;state.market3.exclusive.push({origin,holder:r.id,until:state.week+12});log(r.name+' získal prioritní dodávky',ORIGINS[origin].name+' je na 12 týdnů o 12 % dražší pro běžné nákupy.');}}}if(state.week%16===0&&!state.buyout){const r=state.rivals.filter(r=>!r.bankrupt).sort((a,b)=>b.cash-a.cash)[0];if(r&&r.cash>800000){state.buyout={rival:r.id,amount:round(Math.min(companyValue()*1.15,r.cash*.7)),due:state.week+3};log('Nabídka na odkup firmy',r.name+' nabízí '+money(state.buyout.amount)+'. Můžeš ji přijmout nebo odmítnout.')}}if(state.buyout?.due<state.week)state.buyout=null;};
addRegion=function(city,index){CORE.addRegion(city,index);state.regions.at(-1).manager=recruitProfile(index)};
function recordMenuSales(s){const m=s.menuStats||menuSummary(s),served=s.last?.served||0;s.lastItems=[...m.drinks.map(d=>({id:d.id,count:round(served*d.weight/m.total),revenue:round(served*d.weight/m.total*d.price),minutes:d.minutes})),...m.food.map(f=>({id:f.id,count:round(served*f.rate),revenue:round(served*f.rate*f.price),minutes:f.minutes}))];}
function scenarioProgress(){const sc=SCENARIOS[state.scenario],cities=new Set(state.stores.map(s=>loc(s.id).city)).size,profitable=state.history.slice(-4).length===4&&state.history.slice(-4).every(h=>h.profit>0),rep=state.scenario==='premium'?85:state.scenario==='family'?65:75;const done=state.scenario==='rescue'?profitable&&state.debt<=500000:state.stores.length>=sc.goal&&cities>=sc.cities&&state.reputation>=rep&&profitable;return {done,profitable,rep,stores:sc.goal,cities:sc.cities};}
nextWeek=function(){guard();const initialCash=state.cash;state.turnLedger3={transport:0,crises:state.pendingExpense3||0,writeoff:state.pendingWriteoff3||0,supply:0,auctions:0};state.pendingExpense3=0;state.pendingWriteoff3=0;for(const a of staffAssignments())a.entity.manager=person3(a.person);expireTransfers();processTransfers();processIncidents();processSupply();processAuctions();for(const s of state.stores){store3(s);for(const e of Object.values(s.equipment))e.condition=clamp(e.condition-.6,25,100);s.serviceCondition=clamp(s.serviceCondition-.15,75,100);if(s.manager&&state.policy3.autoCrises&&s.serviceCondition<85&&state.policy3.crisisLimit>=5000&&state.cash>weeklyFixed()*3+5000){state.cash-=5000;state.turnLedger3.crises+=5000;s.serviceCondition=100;log('Preventivní kontrola: '+loc(s.id).name,'Manažer obnovil provozní stav v limitu 5 000 Kč.');}}
const h=CORE.nextWeek(),ledger=state.turnLedger3,warehouses=state.warehouses.reduce((a,w)=>a+w.upkeep,0);state.cash-=warehouses;h.expenses=round(h.expenses+warehouses+ledger.transport+ledger.crises);h.spoil=round(h.spoil+ledger.writeoff);h.profit=round(h.profit-warehouses-ledger.transport-ledger.crises-ledger.writeoff);h.cash=round(state.cash);h.cashChange=round(state.cash-initialCash);h.margin=h.revenue?h.profit/h.revenue:0;Object.assign(h.detail,{warehouses:round(warehouses),transport:round(ledger.transport),crises:round(ledger.crises),supplyPurchases:round(ledger.supply),auctionRights:round(ledger.auctions)});delete state.turnLedger3;const weeklyLog=state.logs.find(l=>l.week===h.week&&l.text.startsWith('Týden '+h.week+':'));if(weeklyLog)weeklyLog.text='Týden '+h.week+': '+money(h.profit);state.stores.forEach(recordMenuSales);if(state.cash<0)state.over=true;if(!state.over){processCareers();if((state.week-1)%difficulty3().eventEvery===0)generateIncident();const progress=scenarioProgress();if(!state.scenarioWon&&progress.done){state.scenarioWon=true;state.badges.push({id:state.scenario,week:state.week});log('Scénář dokončen: '+SCENARIOS[state.scenario].name,'Můžeš pokračovat v rozvoji firmy.');}}return h;};
function planCost(plan){if(plan.kind==='store')return loc(plan.target)?.setup;if(plan.kind==='roaster')return ROASTER_OPTIONS.find(r=>r.id===plan.target)?.cost;if(plan.kind==='estate')return ESTATES.find(e=>e.id===plan.target)?.cost;if(plan.kind==='office')return OFFICE_OPTIONS.find(e=>e.id===plan.target)?.cost;if(plan.kind==='warehouse')return Number(plan.size)*95;if(plan.kind==='equipment')return EQUIPMENT[plan.target]?.cost;throw Error('Neznámá investice.');}
function applyPlan(plan){guard();if(plan.kind==='store')return openStore(plan.target,plan.brand||state.brands[0].id,plan.blend||state.blends[0].id);if(plan.kind==='roaster')return buyRoaster(plan.target,plan.name||'Plánovaná pražírna',plan.city||'Praha');if(plan.kind==='estate')return buyEstate(plan.target);if(plan.kind==='office')return buyOffice(plan.target);if(plan.kind==='warehouse')return buyWarehouse(plan.city,plan.name||'Distribuční sklad',Number(plan.size));if(plan.kind==='equipment')return buyEquipment(plan.store,plan.target);throw Error('Neznámý plán.');}
function simulatePlan(plan,weeks=8){if(!Number.isInteger(weeks)||weeks<4||weeks>26)throw Error('Výhled musí být 4–26 týdnů.');const original=state,results=[];try{for(const scenario of [{name:'Opatrný',factor:.82},{name:'Základní',factor:1},{name:'Příznivý',factor:1.12}]){state=JSON.parse(JSON.stringify(original));state.forecastDemand=scenario.factor;const before=state.cash;applyPlan(plan);const investment=before-state.cash,afterInvestment=state.cash,series=[];for(let i=0;i<weeks&&!state.over;i++){const h=nextWeek();series.push({week:h.week,cash:h.cash,profit:h.profit,cups:h.cups})}results.push({name:scenario.name,factor:scenario.factor,cash:round(state.cash),profit:round(series.reduce((a,h)=>a+h.profit,0)),averageProfit:round(series.reduce((a,h)=>a+h.profit,0)/Math.max(1,series.length)),investment,minCash:round(Math.min(afterInvestment,state.cash,...series.map(h=>h.cash))),reputation:state.reputation,stores:state.stores.length,over:state.over,series});}return {week:original.week,weeks,plan:JSON.parse(JSON.stringify(plan)),results};}finally{state=original}}
validateSave=function(v){const fail=()=>{throw Error('Soubor není platná uložená hra.');};const previous=state;try{if(!v||![1,2,3].includes(v.version))fail();if(v.version===1)return CORE.validateSave(v);if(v.version===2){CORE.validateSave(v);return ensure3(JSON.parse(JSON.stringify(v)))}CORE.validateSave({...v,version:2});const cityValid=c=>CITIES.some(x=>x.name===c),finite=(n,min=0,max=1e12)=>Number.isFinite(n)&&n>=min&&n<=max,string=(s,n=80)=>typeof s==='string'&&s.length<=n;if(!SCENARIOS[v.scenario]||!DIFFICULTIES[v.difficulty]||!Number.isInteger(v.rng)||v.rng<0||v.rng>4294967295||!['planned','express'].includes(v.deliveryPolicy)||!v.policy3||typeof v.policy3.autoCrises!=='boolean'||typeof v.policy3.autoRetention!=='boolean'||!finite(v.policy3.crisisLimit,0,100000)||!finite(v.policy3.retentionLimit,0,50000))fail();for(const k of ['incidents','incidentHistory','offers','offerHistory','auctions','supplyDeals','warehouses','routes','transfers','talents','badges'])if(!Array.isArray(v[k])||v[k].length>500)fail();if(!Array.isArray(v.market3?.exclusive)||v.market3.exclusive.length>100)fail();for(const key of ['brands','blends','roasters','estates','offices','warehouses','routes','transfers','talents']){const ids=v[key].map(e=>key==='talents'?e.pid:e.id);if(ids.some(id=>typeof id!=='string'||!(/^[a-z0-9-]{1,60}$/).test(id))||new Set(ids).size!==ids.length)fail();}for(const s of v.stores){if(!s.menu||!s.equipment||!['balanced','speed','lounge'].includes(s.layout)||!finite(s.seats,1,100)||!finite(s.serviceCondition,25,100)||!finite(s.menuAnchor,35,400)||!Array.isArray(s.lastItems))fail();if(Object.keys(s.menu).length!==Object.keys(MENU).length)fail();for(const [key,item] of Object.entries(s.menu))if(!MENU[key]||typeof item.enabled!=='boolean'||!finite(item.price,35,350))fail();for(const [key,e] of Object.entries(s.equipment))if(!EQUIPMENT[key]||!finite(e.condition,0,100))fail();}if(v.regions.some(r=>!r.manager))fail();for(const r of v.roasters)if(!cityValid(r.zone))fail();for(const b of v.batches)if(!cityValid(b.zone))fail();for(const w of v.warehouses)if(!cityValid(w.zone)||!string(w.id)||!string(w.name,50)||!finite(w.capacity,1,100000)||!finite(w.upkeep,0,100000))fail();for(const r of v.routes)if(!cityValid(r.from)||!cityValid(r.to)||r.from===r.to||!v.blends.some(b=>b.id===r.blend)||!finite(r.kg,5,500)||!['standard','air'].includes(r.mode)||typeof r.active!=='boolean')fail();for(const t of v.transfers){if(!cityValid(t.from)||!cityValid(t.to)||!finite(t.kg)||!finite(t.due)||!Array.isArray(t.batches)||t.batches.length>500||!v.blends.some(b=>b.id===t.blend))fail();for(const b of t.batches)if(![b.kg,b.cost,b.quality,b.roastedWeek].every(n=>finite(n))||!v.blends.some(x=>x.id===b.blend))fail();if(Math.abs(t.kg-t.batches.reduce((a,b)=>a+b.kg,0))>.01)fail();}const persons=[...v.stores,...v.roasters,...v.estates,...v.regions].filter(e=>e.manager).map(e=>e.manager).concat(v.talents);if(new Set(persons.map(p=>p.pid)).size!==persons.length)fail();for(const p of persons)if(!string(p.initials,4)||!string(p.trait,80)||!string(p.pid)||!string(p.name,60)||!finite(p.skill,1,100)||!finite(p.salary,1,50000)||!finite(p.expectedSalary,1,50000)||!finite(p.xp,0,1000)||!finite(p.tenure)||!finite(p.satisfaction,0,100)||!finite(p.ambition,0,100)||!p.strength||!['operations','people','product'].every(k=>finite(p.strength[k],1,100))||!Array.isArray(p.history)||p.history.length>30)fail();for(const i of [...v.incidents,...v.incidentHistory])if(!CRISIS_CHOICES[i.type]||!['store','roaster','shipment'].includes(i.kind)||!string(i.id)||!string(i.target)||!string(i.title,120)||!string(i.details,500)||!finite(i.due)||!finite(i.created))fail();for(const d of v.supplyDeals)if(!ORIGINS[d.origin]||!finite(d.kg,20,500)||!finite(d.price,1,1000)||!finite(d.remaining,1,16)||typeof d.active!=='boolean')fail();for(const a of v.auctions)if(!loc(a.location)||!finite(a.highest)||!finite(a.due)||!finite(a.playerBid)||typeof a.closed!=='boolean'||a.leader!==null&&a.leader!=='player'&&!v.rivals.some(r=>r.id===a.leader))fail();for(const o of [...v.offers,...v.offerHistory])if(!string(o.pid)||!string(o.name,60)||!finite(o.salary,1,50000)||!finite(o.due)||!v.rivals.some(r=>r.id===o.rival))fail();for(const e of v.market3.exclusive)if(!finite(e.until)||e.origin&&!ORIGINS[e.origin]||e.location&&!loc(e.location))fail();for(const k of ['pendingExpense3','pendingWriteoff3'])if(v[k]!==undefined&&!finite(v[k]))fail();if(v.buyout&&(!finite(v.buyout.amount)||!finite(v.buyout.due)||!v.rivals.some(r=>r.id===v.buyout.rival)))fail();v.forecastDemand=1;return v;}finally{state=previous}};
migrateSave=function(v){const previous=state;try{return ensure3(CORE.migrateSave(v))}finally{state=previous}};
// Preserve identities through automatic hiring, acquisitions and release back to the talent pool.
const BASE_ACQUIRE=acquireRival,BASE_REGIONS=autoRegions,BASE_FIXED=weeklyFixed;
acquireRival=function(id){BASE_ACQUIRE(id);for(const s of state.stores)if(s.manager&&!s.manager.pid)s.manager=person3(s.manager)};
autoRegions=function(){BASE_REGIONS();for(const s of state.stores)if(s.manager&&!s.manager.pid)s.manager=recruitProfile(1)};
fire=function(id,kind='store'){guard();const e=entityFor(kind,id);if(!e?.manager)throw Error('Pozice není obsazená.');const p=e.manager;state.talents.push({...p,tenure:0,satisfaction:clamp(p.satisfaction-8,0,100)});if(kind==='region')state.regions=state.regions.filter(r=>r!==e);else e.manager=null;log(p.name+' opouští vedení.','Zkušenosti zůstávají zachované na trhu práce.');};
weeklyFixed=function(){return BASE_FIXED()+state.warehouses.reduce((a,w)=>a+w.upkeep,0)+state.stores.filter(s=>!s.franchise).reduce((a,s)=>a+equipmentEffects(s).cost,0)};
const MANAGER3=autoManager;
autoManager=function(s){const previousStaff=s.staff,decisions=MANAGER3(s),m=s.menuStats;if(s.manager&&s.auto.staff&&state.cash>weeklyFixed()*difficulty3().buffer){const perPerson=(brand(s.brand).concept==='express'?450:380)*1.55/Math.max(.75,m.minutes)*equipmentEffects(s).capacity*(s.layout==='speed'?1.13:s.layout==='lounge'?.9:1)*s.serviceCondition/100,projected=s.last?(s.last.served+s.last.lost):loc(s.id).traffic,desired=clamp(Math.ceil(projected/perPerson)+(s.policy==='growth'?1:0),1,7);s.staff=desired;const filtered=decisions.filter(d=>!d.startsWith('Tým '));if(desired!==previousStaff)filtered.unshift('Tým '+previousStaff+' → '+desired+': '+round(projected)+' očekávaných hostů, kapacita '+round(perPerson)+' na baristu podle menu a zařízení.');return filtered;}return decisions};
stockQuality=function(id='blend-1',city){if(!city)return CORE.stockQuality(id);const lots=state.batches.filter(b=>b.blend===id&&b.zone===city),kg=lots.reduce((a,b)=>a+b.kg,0);return kg?round(lots.reduce((a,b)=>a+b.kg*batchQuality(b),0)/kg):state.deliveryPolicy==='express'?CORE.stockQuality(id):coffeeQuality(id)};
function expireTransfers(){for(const t of [...state.transfers]){const old=t.batches.filter(b=>state.week-b.roastedWeek>=8),loss=old.reduce((a,b)=>a+b.kg*b.cost,0);if(loss){state.turnLedger3.writeoff+=loss;t.batches=t.batches.filter(b=>state.week-b.roastedWeek<8);t.kg=t.batches.reduce((a,b)=>a+b.kg,0);log('Vyřazena káva na cestě','Osm týdnů stará káva z '+t.from+' → '+t.to+'. Odpis '+money(loss)+'.');}if(t.kg<=.001)state.transfers=state.transfers.filter(x=>x.id!==t.id)}}
const SERVICE_ROASTER=maintainRoaster;
maintainRoaster=function(id){SERVICE_ROASTER(id);state.pendingExpense3=(state.pendingExpense3||0)+18000};
